static Specification<Product> hasCategory(String category) {
    return (root, query, cb) -> cb.equal(root.get("category"), category);
}

static Specification<Product> priceGreaterThanOrEqual(double minPrice) {
    return (root, query, cb) -> cb.greaterThanOrEqualTo(root.get("price"), minPrice);
}

Specification<Product> spec = Specification.where(null);
if (category.isPresent()) spec = spec.and(hasCategory(category.get()));
if (minPrice.isPresent()) spec = spec.and(priceGreaterThanOrEqual(minPrice.get()));

List<Product> results = repository.findAll(spec);
